   &ext.ftp.changelog.mode-valueerror;


    7.3.0

     Il parametro mode ora è opzionale. In precedenza era
     obbligatorio.

  &reftitle.examples;



    Esempio di ftp_nb_fput


<?php

$file = 'index.php';

$fp = fopen($file, 'r');

$ftp = ftp_connect($ftp_server);

$login_result = ftp_login($ftp, $ftp_user_name, $ftp_user_pass);

// Avvia il caricamento
$ret = ftp_nb_fput($ftp, $file, $fp, FTP_BINARY);
while ($ret == FTP_MOREDATA) {

   // Esegue qualsiasi altra operazione
   echo ".";

   // Continua il caricamento...
   $ret = ftp_nb_continue($ftp);
}
if ($ret != FTP_FINISHED) {
   echo "Si è verificato un errore durante il caricamento del file...";
   exit(1);
}

fclose($fp);
?>
